function orderMarketDefinitions(definitions = []) {
  const primary = MARKET_PRIMARY_FILTER_IDS.map(id => definitions.find(definition => definition.id === id)).filter(Boolean);
  const structural = SCALAR_MARKET_FILTERS.map(id => definitions.find(definition => definition.id === id)).filter(Boolean);
  const extra = definitions.filter(definition => !SCALAR_MARKET_FILTERS.includes(definition.id) && !MARKET_PRIMARY_FILTER_IDS.includes(definition.id));
  return { structural, primary, extra };
}

function marketFilterSelectionSummary(definitions = [], values = {}) {
  return definitions.filter(definition => !SCALAR_MARKET_FILTERS.includes(definition.id)).flatMap(definition => {
    const selected = categoricalSelection(values[definition.id] ?? definition.defaultValue);
    if (!selected.length) return [];
    const labels = selected.map(value => String(definition.choiceLabels?.[value] ?? value));
    return [{ id: definition.id, label: definition.label, values: selected, labels, count: selected.length,
      text: labels.join(', '), compactText: labels.length > 2 ? `${labels.slice(0, 2).join(', ')} +${labels.length - 2}` : labels.join(', ') }];
  });
}

function marketFilterChangeValue(id, value, singleSelection = false) {
  return SCALAR_MARKET_FILTERS.includes(id) || singleSelection ? value : categoricalSelection(value);
}

const displayDate = value => {
  if (!value || value === 'all') return 'Todo o período';
  return String(value).split('..').map(day => /^\d{4}-\d{2}-\d{2}$/.test(day) ? day.split('-').reverse().join('/') : day).join(' – ');
};

// Parent owns all filter state, including the separate scalar map context.
