  const selectedExtra = selected.filter(selection => extra.some(definition => definition.id === selection.id)).length + (values.population && values.population !== 'light' ? 1 : 0);
  const universe = structural.filter(definition => definition.id === 'population');
  const additional = [...universe, ...extra];
  const date = structural.find(definition => definition.id === 'date');
  const change = (id, value) => onChange?.(id, marketFilterChangeValue(id, value, singleSelection));
  const clear = id => change(id, singleSelection ? 'all' : []);
