 const periodRows=origins.flatMap(vehicleOrigin=>kinds.map(brandKind=>{const count=periodCounts.get(JSON.stringify([vehicleOrigin,brandKind]))??0,originDenominator=originTotals.get(vehicleOrigin)??0;return {vehicleOrigin,vehicleOriginLabel:VEHICLE_ORIGIN_LABELS[vehicleOrigin]??vehicleOrigin,brandKind,brandKindLabel:BRAND_KIND_LABELS[brandKind],count,marketDenominator:model.total,originDenominator,marketShare:ratio(count,model.total),withinOriginShare:ratio(count,originDenominator)};}));
 // Origin coverage is established by reconciled joint counts. An absent sidecar
 // is not evidence of zero national/imported registrations.
