 const rows=monthly.flatMap(m=>origins.flatMap(vehicleOrigin=>kinds.map(brandKind=>{const covered=m.count!==null&&(m.count===0||jointByDate.get(m.date)===m.count),count=covered?(monthCounts.get(JSON.stringify([m.date,vehicleOrigin,brandKind]))??0):null,originDenominator=covered?(monthOriginTotals.get(m.date+'|'+vehicleOrigin)??0):null;return {date:m.date,month:m.month??m.date.slice(0,7),vehicleOrigin,vehicleOriginLabel:VEHICLE_ORIGIN_LABELS[vehicleOrigin]??vehicleOrigin,brandKind,brandKindLabel:BRAND_KIND_LABELS[brandKind],count,originDenominator,marketDenominator:m.count,marketShare:ratio(count,m.count),withinOriginShare:ratio(count,originDenominator),covered};})));
